package com.bank.spark.service;

import com.bank.spark.model.KeyedAmount;
import java.math.BigDecimal;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// Compares how many value-records each strategy shuffles.
public class ShuffleSimulator {

    private static final Logger log = Logger.getLogger(ShuffleSimulator.class.getName());

    // groupByKey: every raw value is shuffled to the key's partition.
    public long groupByKeyShuffleCount(List<KeyedAmount> data) {
        long count = data.size();  // all raw values cross the network
        log.warning(() -> "groupByKey shuffles ALL " + count + " raw values");
        return count;
    }

    // reduceByKey: pre-aggregate per (partition, key); shuffle only partials.
    public long reduceByKeyShuffleCount(List<KeyedAmount> data) {
        Map<String, BigDecimal> partialPerPartitionKey = new HashMap<>();
        for (KeyedAmount k : data) {
            String combineKey = k.getPartition() + "|" + k.getAccountId();
            partialPerPartitionKey.merge(combineKey, k.getAmount(), BigDecimal::add);
        }
        long count = partialPerPartitionKey.size(); // one partial per (partition,key)
        log.info(() -> "reduceByKey shuffles only " + count + " pre-aggregated partials");
        return count;
    }
}
