package com.bank.spark;

import com.bank.spark.model.KeyedAmount;
import com.bank.spark.service.ShuffleSimulator;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: contrast shuffle volume of groupByKey vs reduceByKey.
public class GroupByReduceDemo {

    private static final Logger log = Logger.getLogger(GroupByReduceDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ShuffleSimulator sim = new ShuffleSimulator();

        // 100,000 values across 4 partitions, but only 2 accounts (SAV2001, CUR3001).
        List<KeyedAmount> data = new ArrayList<>();
        for (int i = 0; i < 100_000; i++) {
            String acct = (i % 2 == 0) ? "SAV2001" : "CUR3001";
            data.add(new KeyedAmount(acct, new BigDecimal("3000"), i % 4));
        }

        long g = sim.groupByKeyShuffleCount(data);
        long r = sim.reduceByKeyShuffleCount(data);
        log.info(() -> "reduceByKey shuffles " + (g / Math.max(1, r)) + "x less data");
        log.info("groupByKey vs reduceByKey demo complete.");
    }
}
